182	function toItems(msgs: Message[]): ChatItem[] {
183	  const out: ChatItem[] = [];
184	  const assistantRuns = new Set(msgs.filter((m) => m.role === 'assistant' && m.runId).map((m) => m.runId));
185	  for (const m of msgs) {
186	    out.push({
187	      key: m.role === 'assistant' && m.runId ? 'run:' + m.runId : m.id, id: m.id, role: m.role, content: m.content || '',
188	      attachments: m.attachments || [], createdAt: m.createdAt, userName: m.userName, runId: m.runId, run: m.run, suggestions: m.suggestions,
189	    });
190	    if (m.role === 'user' && m.runId && !assistantRuns.has(m.runId)) {
191	      out.push({ key: 'run:' + m.runId, role: 'assistant', content: '', attachments: [], createdAt: m.createdAt, runId: m.runId, run: m.run });
192	    }
193	  }
194	  return out;
195	}
