423	            ...st.items,
424	            { key: res.messageId || 'local:' + runId, id: res.messageId, role: 'user', content: text, attachments: att.map((u) => u.result!), createdAt: now, runId },
425	            { key: 'run:' + runId, role: 'assistant', content: '', attachments: [], createdAt: now, runId,
426	              run: { id: runId, status: 'queued', model: prefs.model, mode: prefs.mode, startedAt: now, inputTokens: 0, outputTokens: 0, cacheRead: 0, cacheWrite: 0, costUsd: 0 } },
427	          ],
428	          runs: { ...st.runs, [runId]: st.runs[runId] ?? emptyRun(runId, 'queued', Date.now()) },
429	          uploads: [], sending: false,
430	        }));
431	        att.forEach((u) => u.previewUrl && URL.revokeObjectURL(u.previewUrl));
432	        ensureSub(runId, 0);
433	        return true;
434	      } catch (e) {
435	        set({ sending: false, sendError: errInfo(e) });
436	        return false;
437	      }
438	    },
