import type { FastifyPluginAsync } from 'fastify';
import fs from 'node:fs';
import fsp from 'node:fs/promises';
import path from 'node:path';
import { ZipArchive } from 'archiver';
import { z } from 'zod';
import { requireProject, requireUser, type ProjectRow } from '../auth.js';
import type { Ctx } from '../ctx.js';
import { badRequest, conflict, forbidden, notFound } from '../lib/errors.js';
import { contentDisposition, HEAVY_DIRS, looksBinary, mimeFromName, resolveSafe, ZIP_EXCLUDE } from '../lib/safepath.js';

const MAX_READ = 2 * 1024 * 1024;
const MAX_TREE_ENTRIES = 5000;
const MAX_DEPTH = 12;

export interface FileNode {
  name: string;
  path: string;
  type: 'file' | 'dir';
  size?: number;
  mtime?: string;
  children?: FileNode[];
  /** heavy dir (node_modules etc.) or depth/size cap: children not loaded; fetch with ?path= */
  lazy?: boolean;
  symlink?: boolean;
}

const pathBody = z.object({ path: z.string().min(1).max(4096) });
const writeBody = z.object({ path: z.string().min(1).max(4096), content: z.string(), encoding: z.enum(['utf8', 'base64']).optional() });
const renameBody = z.object({ from: z.string().min(1).max(4096), to: z.string().min(1).max(4096), overwrite: z.boolean().optional() });

export function projectRoot(ctx: Ctx, p: ProjectRow): string {
  const root = path.join(ctx.cfg.projectsDir, p.slug);
  fs.mkdirSync(root, { recursive: true });
  return root;
}

async function buildTree(abs: string, rel: string, depth: number, budget: { n: number }): Promise<FileNode[]> {
  let entries: fs.Dirent[];
  try {
    entries = await fsp.readdir(abs, { withFileTypes: true });
  } catch {
    return [];
  }
  entries.sort((a, b) => {
    const ad = a.isDirectory() ? 0 : 1;
    const bd = b.isDirectory() ? 0 : 1;
    return ad - bd || a.name.localeCompare(b.name);
  });
  const out: FileNode[] = [];
  for (const e of entries) {
    if (budget.n-- <= 0) break;
    const childRel = rel ? `${rel}/${e.name}` : e.name;
    const childAbs = path.join(abs, e.name);
    if (e.isSymbolicLink()) {
      // never follow symlinks in the tree; show them as files
      out.push({ name: e.name, path: childRel, type: 'file', symlink: true });
      continue;
    }
    if (e.isDirectory()) {
      const node: FileNode = { name: e.name, path: childRel, type: 'dir' };
      if (HEAVY_DIRS.has(e.name) || depth >= MAX_DEPTH || budget.n <= 0) node.lazy = true;
      else node.children = await buildTree(childAbs, childRel, depth + 1, budget);
      out.push(node);
    } else if (e.isFile()) {
      let size: number | undefined;
      let mtime: string | undefined;
      try {
        const st = await fsp.stat(childAbs);
        size = st.size;
        mtime = st.mtime.toISOString();
      } catch {
        /* vanished */
      }
      out.push({ name: e.name, path: childRel, type: 'file', size, mtime });
    }
  }
  return out;
}

async function addDirToZip(zip: ZipArchive, abs: string, rel: string) {
  let entries: fs.Dirent[];
  try {
    entries = await fsp.readdir(abs, { withFileTypes: true });
  } catch {
    return;
  }
  for (const e of entries) {
    const childAbs = path.join(abs, e.name);
    const childRel = rel ? `${rel}/${e.name}` : e.name;
    if (e.isSymbolicLink()) continue; // never follow symlinks
    if (e.isDirectory()) {
      if (ZIP_EXCLUDE.has(e.name)) continue;
      await addDirToZip(zip, childAbs, childRel);
    } else if (e.isFile()) {
      zip.file(childAbs, { name: childRel });
    }
  }
}

export default (ctx: Ctx): FastifyPluginAsync =>
  async (app) => {
    const { db } = ctx;
    const proj = (req: Parameters<typeof requireUser>[0], min: 'viewer' | 'editor') => {
      const u = requireUser(req);
      const { project } = requireProject(db, u, (req.params as { id: string }).id, min);
      return { project, root: projectRoot(ctx, project) };
    };

    app.get('/api/projects/:id/files/tree', async (req) => {
      const { project, root } = proj(req, 'viewer');
      const q = req.query as { path?: string };
      const { rel, abs } = resolveSafe(root, q.path ?? '', { mustExist: true });
      const st = await fsp.stat(abs);
      if (!st.isDirectory()) throw badRequest('Not a directory');
      const budget = { n: MAX_TREE_ENTRIES };
      // Explicitly requested heavy dirs are listed one level deep (lazy children).
      const isHeavy = rel.split('/').some((s) => HEAVY_DIRS.has(s));
      const children = isHeavy ? await shallow(abs, rel) : await buildTree(abs, rel, 0, budget);
      return {
        name: rel ? path.posix.basename(rel) : project.slug,
        path: rel,
        type: 'dir',
        children,
        truncated: budget.n < 0,
      } satisfies FileNode & { truncated: boolean };
    });

    async function shallow(abs: string, rel: string): Promise<FileNode[]> {
      const entries = await fsp.readdir(abs, { withFileTypes: true });
      entries.sort((a, b) => (a.isDirectory() ? 0 : 1) - (b.isDirectory() ? 0 : 1) || a.name.localeCompare(b.name));
      return entries.slice(0, MAX_TREE_ENTRIES).map((e) => {
        const p = `${rel}/${e.name}`;
        if (e.isSymbolicLink()) return { name: e.name, path: p, type: 'file' as const, symlink: true };
        return e.isDirectory() ? { name: e.name, path: p, type: 'dir' as const, lazy: true } : { name: e.name, path: p, type: 'file' as const };
      });
    }

    app.get('/api/projects/:id/files/content', async (req) => {
      const { root } = proj(req, 'viewer');
      const q = req.query as { path?: string };
      const { rel, abs } = resolveSafe(root, q.path, { mustExist: true, allowRoot: false });
      const st = await fsp.stat(abs);
      if (st.isDirectory()) throw badRequest('Is a directory', 'is_directory');
      const base = { path: rel, size: st.size, mtime: st.mtime.toISOString() };
      if (st.size > MAX_READ) return { ...base, content: null, binary: false, tooLarge: true };
      const buf = await fsp.readFile(abs);
      if (looksBinary(buf)) return { ...base, content: null, binary: true, mime: mimeFromName(rel) };
      return { ...base, content: buf.toString('utf8'), binary: false };
    });

    app.put('/api/projects/:id/files/content', async (req) => {
      const { project, root } = proj(req, 'editor');
      const body = writeBody.parse(req.body);
      const { rel, abs } = resolveSafe(root, body.path, { allowRoot: false });
      const data = body.encoding === 'base64' ? Buffer.from(body.content, 'base64') : Buffer.from(body.content, 'utf8');
      if (data.length > 5 * 1024 * 1024) throw badRequest('File too large', 'too_large');
      try {
        const st = await fsp.lstat(abs);
        if (st.isDirectory()) throw badRequest('Is a directory', 'is_directory');
        if (st.isSymbolicLink()) throw forbidden('Refusing to write through a symlink');
      } catch (err) {
        if ((err as NodeJS.ErrnoException).code !== 'ENOENT') throw err;
      }
      await fsp.mkdir(path.dirname(abs), { recursive: true });
      // re-check parent after mkdir (race with symlink creation)
      resolveSafe(root, path.posix.dirname(rel) === '.' ? '' : path.posix.dirname(rel));
      const tmp = `${abs}.nxtmp-${process.pid}-${Date.now()}`;
      await fsp.writeFile(tmp, data);
      await fsp.rename(tmp, abs);
      const st = await fsp.stat(abs);
      ctx.audit(req, 'file_write', `${project.slug}/${rel}`, { size: data.length });
      return { path: rel, size: st.size, mtime: st.mtime.toISOString() };
    });

    app.post('/api/projects/:id/files/rename', async (req) => {
      const { project, root } = proj(req, 'editor');
      const body = renameBody.parse(req.body);
      const from = resolveSafe(root, body.from, { mustExist: true, allowRoot: false, noFollowLeaf: true });
      const to = resolveSafe(root, body.to, { allowRoot: false });
      if (fs.existsSync(to.abs) && !body.overwrite) throw conflict('Destination already exists', 'exists');
      if ((to.abs + path.sep).startsWith(from.abs + path.sep)) throw badRequest('Cannot move a directory into itself');
      await fsp.mkdir(path.dirname(to.abs), { recursive: true });
      await fsp.rename(from.abs, to.abs);
      ctx.audit(req, 'file_rename', `${project.slug}/${from.rel}`, { to: to.rel });
      return { ok: true, path: to.rel };
    });

    app.post('/api/projects/:id/files/delete', async (req) => {
      const { project, root } = proj(req, 'editor');
      const body = pathBody.parse(req.body);
      const { rel, abs } = resolveSafe(root, body.path, { allowRoot: false, noFollowLeaf: true });
      let st: fs.Stats;
      try {
        st = await fsp.lstat(abs);
      } catch {
        throw notFound('No such file or directory');
      }
      // rm on a symlink removes the link, not its target
      await fsp.rm(abs, { recursive: st.isDirectory(), force: true });
      ctx.audit(req, 'file_delete', `${project.slug}/${rel}`);
      return { ok: true };
    });

    app.post('/api/projects/:id/files/mkdir', async (req) => {
      const { project, root } = proj(req, 'editor');
      const body = pathBody.parse(req.body);
      const { rel, abs } = resolveSafe(root, body.path, { allowRoot: false });
      await fsp.mkdir(abs, { recursive: true });
      ctx.audit(req, 'file_mkdir', `${project.slug}/${rel}`);
      return { ok: true, path: rel };
    });

    app.get('/api/projects/:id/files/download', async (req, reply) => {
      const { project, root } = proj(req, 'viewer');
      const q = req.query as { path?: string };
      const { rel, abs } = resolveSafe(root, q.path ?? '', { mustExist: true });
      const st = await fsp.stat(abs);
      if (st.isFile()) {
        const name = path.basename(abs);
        const mime = mimeFromName(name);
        const active = /^(text\/html|image\/svg|application\/xml|text\/javascript)/.test(mime);
        const inline = (req.query as { inline?: string }).inline === '1' && !active;
        // Correct content-type so <img src> previews work; active types are sandboxed and never rendered inline.
        reply.header('Content-Type', mime.startsWith('text/') ? `${mime}; charset=utf-8` : mime);
        reply.header('Content-Disposition', contentDisposition(inline ? 'inline' : 'attachment', name));
        reply.header('Content-Security-Policy', "default-src 'none'; img-src 'self' data:; style-src 'unsafe-inline'; sandbox");
        reply.header('Cache-Control', 'no-cache');
        reply.header('Content-Length', st.size);
        return reply.send(fs.createReadStream(abs));
      }
      const zipName = `${rel ? path.posix.basename(rel) : project.slug}.zip`;
      const zip = new ZipArchive({ zlib: { level: 6 } });
      zip.on('warning', (err) => ctx.log.warn({ err: err.message }, 'zip warning'));
      zip.on('error', (err) => {
        ctx.log.error({ err: err.message }, 'zip error');
        reply.raw.destroy(err);
      });
      reply.header('Content-Type', 'application/zip');
      reply.header('Content-Disposition', contentDisposition('attachment', zipName));
      await addDirToZip(zip, abs, '');
      void zip.finalize();
      return reply.send(zip);
    });
  };
import type { FastifyPluginAsync } from 'fastify';
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { pipeline } from 'node:stream/promises';
import sharp from 'sharp';
import { request, FormData } from 'undici';
import { projectRole, requireProject, requireUser, type UserRow } from '../auth.js';
import type { Ctx } from '../ctx.js';
import { now } from '../db.js';
import { attachmentDTO, type UploadRow } from '../dto.js';
import { badRequest, forbidden, HttpError, notFound } from '../lib/errors.js';
import { contentDisposition, mimeFromName, sanitizeFilename } from '../lib/safepath.js';

const THUMB = '.thumb.webp';
const THUMBABLE = new Set(['image/png', 'image/jpeg', 'image/webp', 'image/gif', 'image/avif', 'image/tiff', 'image/bmp']);
const ACTIVE_TYPES = /^(text\/html|application\/xhtml|image\/svg|application\/xml|text\/xml|text\/javascript|application\/javascript)/i;
const INLINE_TYPES = /^(image\/|audio\/|video\/|application\/pdf|text\/plain)/i;

function cleanMime(m: string | undefined, filename: string): string {
  const s = (m ?? '').toLowerCase().split(';')[0]!.trim();
  if (!s || s === 'application/octet-stream' || !/^[a-z0-9.+-]+\/[a-z0-9.+-]+$/.test(s)) return mimeFromName(filename);
  return s;
}

export function canReadUpload(ctx: Ctx, u: UserRow, up: UploadRow): boolean {
  if (u.role === 'admin' || up.user_id === u.id) return true;
  if (up.project_id && projectRole(ctx.db, u, up.project_id)) return true;
  return false;
}

export default (ctx: Ctx): FastifyPluginAsync =>
  async (app) => {
    const { db, cfg } = ctx;

    app.post('/api/uploads', async (req, reply) => {
      const u = requireUser(req);
      if (!req.isMultipart()) throw badRequest('Expected multipart/form-data');
      const created: UploadRow[] = [];
      let projectId: string | null = null;
      try {
        for await (const part of req.parts()) {
          if (part.type === 'field') {
            if (part.fieldname === 'projectId' && typeof part.value === 'string' && part.value) {
              requireProject(db, u, part.value, 'editor');
              projectId = part.value;
            }
            continue;
          }
          const id = crypto.randomUUID();
          const filename = sanitizeFilename(part.filename || 'file');
          const dir = path.join(cfg.uploadsDir, id);
          fs.mkdirSync(dir, { recursive: true });
          const dest = path.join(dir, filename === THUMB ? `_${filename}` : filename);
          try {
            await pipeline(part.file, fs.createWriteStream(dest, { flags: 'wx' }));
          } catch (err) {
            fs.rmSync(dir, { recursive: true, force: true });
            throw err;
          }
          if (part.file.truncated) {
            fs.rmSync(dir, { recursive: true, force: true });
            throw new HttpError(413, 'too_large', 'File exceeds the 50 MB limit');
          }
          const size = fs.statSync(dest).size;
          const mime = cleanMime(part.mimetype, filename);
          let hasThumb = 0;
          if (THUMBABLE.has(mime)) {
            try {
              await sharp(dest, { limitInputPixels: 100_000_000, animated: false })
                .rotate()
                .resize(320, 320, { fit: 'inside', withoutEnlargement: true })
                .webp({ quality: 78 })
                .toFile(path.join(dir, THUMB));
              hasThumb = 1;
            } catch (err) {
              ctx.log.warn({ err: (err as Error).message }, 'thumbnail failed');
            }
          }
          const row: UploadRow = { id, user_id: u.id, project_id: null, filename, mime, size, path: dest, has_thumb: hasThumb, created_at: now() };
          created.push(row);
        }
      } catch (err) {
        for (const r of created) fs.rmSync(path.dirname(r.path), { recursive: true, force: true });
        const e = err as { code?: string };
        if (e.code === 'FST_REQ_FILE_TOO_LARGE') throw new HttpError(413, 'too_large', 'File exceeds the 50 MB limit');
        throw err;
      }
      if (!created.length) throw badRequest('No file in upload', 'no_file');
      const ins = db.prepare(
        `INSERT INTO uploads(id, user_id, project_id, filename, mime, size, path, has_thumb, created_at) VALUES (?,?,?,?,?,?,?,?,?)`,
      );
      db.transaction(() => {
        for (const r of created) {
          r.project_id = projectId;
          ins.run(r.id, r.user_id, r.project_id, r.filename, r.mime, r.size, r.path, r.has_thumb, r.created_at);
        }
      })();
      ctx.audit(req, 'upload', created.map((r) => r.id).join(','), created.map((r) => ({ filename: r.filename, size: r.size, mime: r.mime })));
      reply.code(201);
      const dtos = created.map(attachmentDTO);
      return dtos.length === 1 ? dtos[0] : { ...dtos[0], files: dtos };
    });

    const loadUpload = (req: { params: unknown; user: UserRow | null }) => {
      const u = requireUser(req as never);
      const id = (req.params as { id: string }).id;
      if (!/^[0-9a-f-]{36}$/.test(id)) throw notFound('Upload not found');
      const up = db.prepare(`SELECT * FROM uploads WHERE id = ?`).get(id) as UploadRow | undefined;
      if (!up) throw notFound('Upload not found');
      if (!canReadUpload(ctx, u, up)) throw notFound('Upload not found');
      // defence in depth: stored path must live under UPLOADS_DIR/<id>/
      const real = fs.existsSync(up.path) ? fs.realpathSync(up.path) : '';
      if (!real || !real.startsWith(fs.realpathSync(path.join(cfg.uploadsDir, up.id)) + path.sep)) throw notFound('Upload file missing');
      return up;
    };

    app.get('/api/uploads/:id', async (req, reply) => {
      const up = loadUpload(req);
      const q = req.query as { download?: string };
      const active = ACTIVE_TYPES.test(up.mime);
      const inline = !active && INLINE_TYPES.test(up.mime) && q.download !== '1';
      reply.header('Content-Type', active ? 'application/octet-stream' : up.mime);
      reply.header('Content-Disposition', contentDisposition(inline ? 'inline' : 'attachment', up.filename));
      reply.header('Content-Security-Policy', "default-src 'none'; img-src 'self' data:; media-src 'self'; style-src 'unsafe-inline'; sandbox");
      reply.header('Cache-Control', 'private, max-age=86400');
      return reply.sendFile(path.basename(up.path), path.dirname(up.path), { contentType: false, cacheControl: false });
    });

    app.get('/api/uploads/:id/thumb', async (req, reply) => {
      const up = loadUpload(req);
      if (!up.has_thumb) throw notFound('No thumbnail');
      reply.header('Content-Type', 'image/webp');
      reply.header('Cache-Control', 'private, max-age=604800');
      return reply.sendFile(THUMB, path.dirname(up.path), { contentType: false, cacheControl: false });
    });

    app.delete('/api/uploads/:id', async (req) => {
      const u = requireUser(req);
      const up = db.prepare(`SELECT * FROM uploads WHERE id = ?`).get((req.params as { id: string }).id) as UploadRow | undefined;
      if (!up) throw notFound('Upload not found');
      if (up.user_id !== u.id && u.role !== 'admin') throw forbidden();
      const referenced = db.prepare(`SELECT 1 FROM messages WHERE attachments LIKE ? LIMIT 1`).get(`%"${up.id}"%`);
      if (referenced) return { ok: true, kept: true }; // referenced by chat history; keep
      db.prepare(`DELETE FROM uploads WHERE id = ?`).run(up.id);
      fs.rmSync(path.join(cfg.uploadsDir, up.id), { recursive: true, force: true });
      return { ok: true };
    });

    // ---- speech-to-text proxy ----
    app.post(
      '/api/transcribe',
      { config: { rateLimit: { max: 30, timeWindow: '1 minute', keyGenerator: (r) => r.user?.id ?? r.clientIp } } },
      async (req) => {
        requireUser(req);
        if (!req.isMultipart()) throw badRequest('Expected multipart/form-data');
        const form = new FormData();
        let gotAudio = false;
        for await (const part of req.parts({ limits: { fileSize: 25 * 1024 * 1024 } })) {
          if (part.type === 'field') {
            if ((part.fieldname === 'language' || part.fieldname === 'prompt') && typeof part.value === 'string' && part.value.length <= 1000)
              form.append(part.fieldname, part.value);
            continue;
          }
          if (gotAudio || (part.fieldname !== 'audio' && part.fieldname !== 'file')) {
            part.file.resume();
            continue;
          }
          const buf = await part.toBuffer().catch((err: { code?: string }) => {
            if (err.code === 'FST_REQ_FILE_TOO_LARGE') throw new HttpError(413, 'too_large', 'Audio too large');
            throw err;
          });
          const type = cleanMime(part.mimetype, part.filename || 'audio.webm');
          form.append('audio', new Blob([new Uint8Array(buf)], { type }), sanitizeFilename(part.filename || 'audio.webm'));
          gotAudio = true;
        }
        if (!gotAudio) throw badRequest('Missing audio', 'no_file');
        let res;
        try {
          res = await request(`${cfg.whisperUrl}/transcribe`, { method: 'POST', body: form, headersTimeout: 120_000, bodyTimeout: 120_000 });
        } catch (err) {
          throw new HttpError(502, 'whisper_unavailable', `Speech-to-text service unavailable: ${(err as Error).message}`);
        }
        const text = await res.body.text();
        if (res.statusCode === 413) throw new HttpError(413, 'too_large', 'Recording is too long or too large to transcribe');
        if (res.statusCode === 422) throw new HttpError(422, 'undecodable_audio', 'Could not decode the recorded audio');
        if (res.statusCode >= 400) throw new HttpError(502, 'whisper_error', `Transcription failed (${res.statusCode})`);
        try {
          const j = JSON.parse(text) as { text?: string; language?: string; durationMs?: number; processingMs?: number };
          return { text: (j.text ?? '').trim(), language: j.language ?? null, durationMs: j.durationMs ?? null, processingMs: j.processingMs ?? null };
        } catch {
          throw new HttpError(502, 'whisper_error', 'Invalid response from speech-to-text service');
        }
      },
    );
  };

import { memo, useCallback, useMemo, useState } from 'react';
import clsx from 'clsx';
import {
  ChevronRight, Download, File as FileIcon, FileCode, FileJson, FilePlus, Folder, FolderOpen, FolderPlus, Image as ImageIcon,
  MessageSquare, MessagesSquare, Pencil, Plus, RefreshCw, Trash, FileText, Code as CodeIcon, Ellipsis,
} from 'lucide-react';
import type { FileNode } from '@/lib/types';
import { useWs, isTerminal } from './store';
import { ContextMenu, IconBtn, InlineInput, MenuItem, MenuSep, Spin } from './ui';
import { IMAGE_RE } from './toolFormat';

// ---------- File tree ----------
function fileIcon(name: string) {
  if (IMAGE_RE.test(name)) return <ImageIcon size={14} className="text-warm/80" />;
  if (/\.(json|lock)$/i.test(name)) return <FileJson size={14} className="text-warn/70" />;
  if (/\.(md|txt|mdx)$/i.test(name)) return <FileText size={14} className="text-muted" />;
  if (/\.(tsx?|jsx?|mjs|cjs|py|go|rs|rb|java|c|cpp|h|cs|php|sh|vue|svelte)$/i.test(name)) return <FileCode size={14} className="text-pink/70" />;
  if (/\.(css|scss|less|html?)$/i.test(name)) return <CodeIcon size={14} className="text-violet/80" />;
  return <FileIcon size={14} className="text-muted/80" />;
}

type Pending = { kind: 'file' | 'dir'; parent: string } | null;
const join = (dir: string, name: string) => (dir ? `${dir}/${name}` : name);
const parentOf = (p: string) => (p.includes('/') ? p.slice(0, p.lastIndexOf('/')) : '');

function sortNodes(nodes: FileNode[]) {
  return nodes.slice().sort((a, b) => (a.type !== b.type ? (a.type === 'dir' ? -1 : 1) : a.name.localeCompare(b.name, undefined, { numeric: true })));
}

const TreeNode = memo(function TreeNode({ node, depth, onMenu, renaming, setRenaming, pending, setPending }: {
  node: FileNode; depth: number; onMenu: (e: React.MouseEvent, n: FileNode) => void;
  renaming: string | null; setRenaming: (p: string | null) => void; pending: Pending; setPending: (p: Pending) => void;
}) {
  const expanded = useWs((s) => !!s.expanded[node.path]);
  const flash = useWs((s) => s.flashes[node.path]);
  const active = useWs((s) => s.activeTab === node.path && s.rightTab === 'code');
  const { toggleDir, openFile, renamePath, createFile, createDir } = useWs.getState();
  const isDir = node.type === 'dir';
  const pad = 8 + depth * 12;
  const childPending = pending && pending.parent === node.path;

  return (
    <div>
      <div
        role="treeitem" aria-expanded={isDir ? expanded : undefined} tabIndex={0}
        onClick={() => (isDir ? toggleDir(node.path) : openFile(node.path))}
        onKeyDown={(e) => { if (e.key === 'Enter') isDir ? toggleDir(node.path) : openFile(node.path); if (e.key === 'F2') setRenaming(node.path); }}
        onContextMenu={(e) => onMenu(e, node)}
        draggable={!isDir}
        onDragStart={(e) => { e.dataTransfer.setData('text/plain', node.path); e.dataTransfer.setData('application/x-nx-path', node.path); }}
        className={clsx(
          'group relative flex h-[26px] cursor-pointer select-none items-center gap-1.5 rounded-md pr-1 text-[13px] outline-none transition-colors',
          active ? 'bg-pink/[.12] text-ink' : 'text-ink/80 hover:bg-white/[.04] hover:text-ink focus-visible:bg-white/[.05]',
          flash && 'nxw-flash',
        )}
        style={{ paddingLeft: pad }}
      >
        {active && <span className="absolute left-0 top-1 bottom-1 w-[2px] rounded-full bg-pink shadow-[0_0_8px_var(--pink)]" />}
        {isDir ? (
          <>
            <ChevronRight size={12} className={clsx('shrink-0 text-muted/60 transition-transform', expanded && 'rotate-90')} />
            {expanded ? <FolderOpen size={14} className="shrink-0 text-pink/80" /> : <Folder size={14} className="shrink-0 text-pink/60" />}
          </>
        ) : (
          <><span className="w-3 shrink-0" />{fileIcon(node.name)}</>
        )}
        {renaming === node.path ? (
          <InlineInput initial={node.name} onCancel={() => setRenaming(null)}
            onCommit={(v) => { setRenaming(null); renamePath(node.path, join(parentOf(node.path), v)).catch(() => {}); }} />
        ) : (
          <span className="min-w-0 flex-1 truncate">{node.name}</span>
        )}
        <button type="button" onClick={(e) => { e.stopPropagation(); onMenu(e, node); }}
          className="hidden h-5 w-5 shrink-0 items-center justify-center rounded text-muted hover:bg-white/10 hover:text-ink group-hover:flex">
          <Ellipsis size={13} />
        </button>
      </div>
      {isDir && expanded && (
        <div>
          {childPending && (
            <div className="flex h-[26px] items-center gap-1.5 pr-2" style={{ paddingLeft: pad + 12 + 15 }}>
              {pending!.kind === 'dir' ? <Folder size={14} className="shrink-0 text-pink/60" /> : <FileIcon size={14} className="shrink-0 text-muted" />}
              <InlineInput initial="" placeholder={pending!.kind === 'dir' ? 'folder name' : 'file name'} onCancel={() => setPending(null)}
                onCommit={(v) => { setPending(null); (pending!.kind === 'dir' ? createDir : createFile)(join(node.path, v)).catch(() => {}); }} />
            </div>
          )}
          {sortNodes(node.children ?? []).map((c) => (
            <TreeNode key={c.path} node={c} depth={depth + 1} onMenu={onMenu} renaming={renaming} setRenaming={setRenaming} pending={pending} setPending={setPending} />
          ))}
        </div>
      )}
    </div>
  );
});

function FileTree() {
  const tree = useWs((s) => s.tree);
  const treeError = useWs((s) => s.treeError);
  const canEdit = useWs((s) => s.canEdit);
  const project = useWs((s) => s.project);
  const { refreshTree, toggleDir, openFile, deletePath, createFile, createDir } = useWs.getState();
  const [menu, setMenu] = useState<{ at: { x: number; y: number }; node: FileNode | null } | null>(null);
  const [renaming, setRenaming] = useState<string | null>(null);
  const [pending, setPending] = useState<Pending>(null);
  const sorted = useMemo(() => (tree ? sortNodes(tree) : null), [tree]);

  const onMenu = useCallback((e: React.MouseEvent, node: FileNode | null) => {
    e.preventDefault(); e.stopPropagation();
    setMenu({ at: { x: e.clientX, y: e.clientY }, node });
  }, []);

  const startNew = (kind: 'file' | 'dir', node: FileNode | null) => {
    const parent = node ? (node.type === 'dir' ? node.path : parentOf(node.path)) : '';
    if (parent) toggleDir(parent, true);
    setPending({ kind, parent });
  };
  const download = (path: string) => { if (project) window.open(`/api/projects/${project.id}/files/download?path=${encodeURIComponent(path)}`, '_blank'); };

  return (
    <div className="flex h-full min-h-0 flex-col" onContextMenu={(e) => onMenu(e, null)}>
      <div className="flex h-9 shrink-0 items-center gap-0.5 px-2">
        <span className="flex-1 pl-1 text-[10.5px] font-medium uppercase tracking-[.16em] text-muted/80">Explorer</span>
        {canEdit && <IconBtn label="New file" onClick={() => startNew('file', null)}><FilePlus size={14} /></IconBtn>}
        {canEdit && <IconBtn label="New folder" onClick={() => startNew('dir', null)}><FolderPlus size={14} /></IconBtn>}
        <IconBtn label="Refresh" onClick={() => refreshTree()}><RefreshCw size={13} /></IconBtn>
      </div>
      <div role="tree" className="nxw-scroll min-h-0 flex-1 overflow-y-auto px-1.5 pb-4">
        {pending && pending.parent === '' && (
          <div className="flex h-[26px] items-center gap-1.5 pl-[23px] pr-2">
            {pending.kind === 'dir' ? <Folder size={14} className="shrink-0 text-pink/60" /> : <FileIcon size={14} className="shrink-0 text-muted" />}
            <InlineInput initial="" placeholder={pending.kind === 'dir' ? 'folder name' : 'file name (e.g. src/app.ts)'} onCancel={() => setPending(null)}
              onCommit={(v) => { setPending(null); (pending.kind === 'dir' ? createDir : createFile)(v).catch(() => {}); }} />
          </div>
        )}
        {treeError && !sorted ? (
          <div className="px-3 py-6 text-center text-[12px] text-bad">{treeError}</div>
        ) : !sorted ? (
          <div className="flex justify-center py-8"><Spin /></div>
        ) : !sorted.length && !pending ? (
          <div className="px-4 py-10 text-center text-[12.5px] leading-relaxed text-muted">
            <FolderOpen size={22} className="mx-auto mb-2 text-pink/50" />
            No files yet.<br />Ask Claude to create something,<br />or drop files in the chat.
          </div>
        ) : (
          sorted.map((n) => <TreeNode key={n.path} node={n} depth={0} onMenu={onMenu} renaming={renaming} setRenaming={setRenaming} pending={pending} setPending={setPending} />)
        )}
      </div>
      <ContextMenu at={menu?.at ?? null} onClose={() => setMenu(null)}>
        {menu?.node && menu.node.type === 'file' && <MenuItem icon={<CodeIcon size={14} />} onClick={() => openFile(menu.node!.path)}>Open in editor</MenuItem>}
        {canEdit && <MenuItem icon={<FilePlus size={14} />} onClick={() => startNew('file', menu?.node ?? null)}>New file</MenuItem>}
        {canEdit && <MenuItem icon={<FolderPlus size={14} />} onClick={() => startNew('dir', menu?.node ?? null)}>New folder</MenuItem>}
        {menu?.node && (
          <>
            {canEdit && <MenuItem icon={<Pencil size={14} />} hint="F2" onClick={() => setRenaming(menu.node!.path)}>Rename</MenuItem>}
            <MenuItem icon={<Download size={14} />} onClick={() => download(menu.node!.path)}>{menu.node.type === 'dir' ? 'Download as zip' : 'Download'}</MenuItem>
            <MenuItem icon={<CodeIcon size={14} />} onClick={() => navigator.clipboard?.writeText(menu.node!.path)}>Copy path</MenuItem>
            {canEdit && (
              <>
                <MenuSep />
                <MenuItem danger icon={<Trash size={14} />} onClick={() => {
                  const n = menu.node!;
                  if (window.confirm(`Delete ${n.type === 'dir' ? 'folder' : 'file'} “${n.path}”? This cannot be undone.`)) deletePath(n.path).catch(() => {});
                }}>Delete</MenuItem>
              </>
            )}
          </>
        )}
      </ContextMenu>
    </div>
  );
}

// ---------- Conversations ----------
function relTime(iso?: string) {
  if (!iso) return '';
  const d = Date.now() - Date.parse(iso);
  if (d < 60_000) return 'now';
  if (d < 3_600_000) return `${Math.floor(d / 60_000)}m`;
  if (d < 86_400_000) return `${Math.floor(d / 3_600_000)}h`;
  if (d < 7 * 86_400_000) return `${Math.floor(d / 86_400_000)}d`;
  return new Date(iso).toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
}

function ConversationList() {
  const conversations = useWs((s) => s.conversations);
  const activeConvId = useWs((s) => s.activeConvId);
  const convLoading = useWs((s) => s.convLoading);
  const canEdit = useWs((s) => s.canEdit);
  const runningConv = useWs((s) => (s.items.some((i) => i.runId && s.runs[i.runId] && !isTerminal(s.runs[i.runId].status)) ? s.activeConvId : null));
  const { selectConversation, newConversation, renameConversation, deleteConversation } = useWs.getState();
  const [renaming, setRenaming] = useState<string | null>(null);
  const [menu, setMenu] = useState<{ at: { x: number; y: number }; id: string } | null>(null);
  const [q, setQ] = useState('');
  const list = q ? conversations.filter((c) => (c.title || '').toLowerCase().includes(q.toLowerCase())) : conversations;

  return (
    <div className="flex h-full min-h-0 flex-col">
      <div className="flex shrink-0 items-center gap-1.5 p-2">
        <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search chats…"
          className="h-8 min-w-0 flex-1 rounded-lg border border-line bg-bg/60 px-2.5 text-[12.5px] text-ink outline-none placeholder:text-muted/60 focus:border-pink/40" />
        {canEdit && (
          <button type="button" onClick={newConversation}
            className="inline-flex h-8 shrink-0 items-center gap-1 rounded-lg border border-pink/40 bg-pink/10 px-2.5 text-[12.5px] text-hot transition hover:bg-pink/20 hover:shadow-[0_0_16px_-4px_rgba(255,62,138,.7)]">
            <Plus size={14} /> New
          </button>
        )}
      </div>
      <div className="nxw-scroll min-h-0 flex-1 space-y-px overflow-y-auto px-1.5 pb-4">
        {convLoading && !conversations.length && <div className="flex justify-center py-8"><Spin /></div>}
        {!convLoading && !list.length && (
          <div className="px-4 py-10 text-center text-[12.5px] text-muted">
            <MessagesSquare size={22} className="mx-auto mb-2 text-pink/50" />
            {q ? 'No matches.' : 'No conversations yet.'}
          </div>
        )}
        {list.map((c) => {
          const active = c.id === activeConvId;
          return (
            <div key={c.id}
              role="button" tabIndex={0}
              onClick={() => selectConversation(c.id)}
              onDoubleClick={() => canEdit && setRenaming(c.id)}
              onContextMenu={(e) => { e.preventDefault(); setMenu({ at: { x: e.clientX, y: e.clientY }, id: c.id }); }}
              className={clsx('group relative flex cursor-pointer items-center gap-2 rounded-lg px-2.5 py-2 transition-colors',
                active ? 'bg-pink/[.10] text-ink' : 'text-ink/75 hover:bg-white/[.04] hover:text-ink')}>
              {active && <span className="absolute left-0 top-2 bottom-2 w-[2px] rounded-full bg-pink shadow-[0_0_8px_var(--pink)]" />}
              {runningConv === c.id ? <Spin className="h-3 w-3 shrink-0" /> : <MessageSquare size={14} className={clsx('shrink-0', active ? 'text-pink' : 'text-muted/60')} />}
              {renaming === c.id ? (
                <InlineInput initial={c.title || ''} onCancel={() => setRenaming(null)} onCommit={(v) => { setRenaming(null); renameConversation(c.id, v); }} />
              ) : (
                <span className="min-w-0 flex-1 truncate text-[13px]">{c.title || 'Untitled'}</span>
              )}
              <span className="shrink-0 text-[10.5px] text-muted/60 group-hover:hidden">{relTime(c.updatedAt || c.createdAt)}</span>
              {canEdit && (
                <button type="button" onClick={(e) => { e.stopPropagation(); setMenu({ at: { x: e.clientX, y: e.clientY }, id: c.id }); }}
                  className="hidden h-5 w-5 shrink-0 items-center justify-center rounded text-muted hover:bg-white/10 hover:text-ink group-hover:flex">
                  <Ellipsis size={13} />
                </button>
              )}
            </div>
          );
        })}
      </div>
      <ContextMenu at={menu?.at ?? null} onClose={() => setMenu(null)}>
        {canEdit && <MenuItem icon={<Pencil size={14} />} onClick={() => setRenaming(menu!.id)}>Rename</MenuItem>}
        {canEdit && <MenuItem danger icon={<Trash size={14} />} onClick={() => {
          const c = conversations.find((x) => x.id === menu!.id);
          if (window.confirm(`Delete conversation “${c?.title || 'Untitled'}”?`)) deleteConversation(menu!.id);
        }}>Delete</MenuItem>}
      </ContextMenu>
    </div>
  );
}

