const AdminRoutes = lazy(() => import('@/features/admin/AdminRoutes'));
const UsagePage = lazy(() => import('@/features/usage/UsagePage'));

/** Gate for authenticated routes; redirects to /login?next=… */
function RequireAuth({ children }: { children?: ReactNode }) {
  const { user, loading } = useAuth();
  const loc = useLocation();
  if (loading) return <BootScreen />;
  if (!user) return <Navigate to={`/login?next=${encodeURIComponent(loc.pathname + loc.search)}`} replace />;
  return <>{children ?? <Outlet />}</>;
}
function RequireAdmin({ children }: { children: ReactNode }) {
  const user = useAuth((s) => s.user);
  if (user?.role !== 'admin') return <NotFound forbidden />;
  return <>{children}</>;
}
function GuestOnly({ children }: { children: ReactNode }) {
  const { user, loading } = useAuth();
  const loc = useLocation();
  if (loading) return <BootScreen />;
  if (user) {
    const next = new URLSearchParams(loc.search).get('next');
    return <Navigate to={next && next.startsWith('/') && !next.startsWith('//') ? next : '/'} replace />;
  }
  return <>{children}</>;
}

/** Things mounted once a user is signed in (live socket, palette, global modals). */
function AuthedGlobals() {
  const user = useAuth((s) => s.user);
  useEffect(() => { if (user) live.connect(); }, [user]);
  if (!user) return null;
  return (<><CommandPalette /><NewProjectModal /></>);
}

export default function App() {
  const refresh = useAuth((s) => s.refresh);
  useEffect(() => { refresh(); }, [refresh]);
  return (
    <BrowserRouter>
      <Suspense fallback={<BootScreen />}>
        <Routes>
          <Route path="/login" element={<GuestOnly><LoginPage /></GuestOnly>} />
          <Route element={<RequireAuth />}>
            <Route path="/p/:slug/*" element={<WorkspacePage />} />
            <Route element={<AppShell />}>
              <Route index element={<NexusPage />} />
              <Route path="/usage" element={<UsagePage />} />
              <Route path="/admin/*" element={<RequireAdmin><AdminRoutes /></RequireAdmin>} />
              <Route path="*" element={<NotFound />} />
            </Route>
          </Route>
        </Routes>
      </Suspense>
      <AuthedGlobals />
      <Toaster />
    </BrowserRouter>
  );
}

